</div>
<script>(function(){const status=document.getElementById('facBoStatus'),search=document.getElementById('facBoSearch'),rows=[...document.querySelectorAll('.fac-bo-row')],empty=document.getElementById('facBoEmpty');if(!status||!search)return;function filter(){let n=0;for(const row of rows){const show=(!status.value||row.dataset.status===status.value)&&(!search.value.trim()||row.textContent.toLocaleLowerCase('fr').includes(search.value.trim().toLocaleLowerCase('fr')));row.hidden=!show;if(show)n++;}empty.hidden=n!==0;}status.addEventListener('change',filter);search.addEventListener('input',filter)})();</script>
